            "from collections import Counter\nvotes = [\"да\", \"нет\", \"да\", \"да\", \"нет\"]\ncounts = Counter(votes)\nprint(counts[\"да\"])\nprint(counts.most_common(1))",
            "from collections import Counter\nvotes = [\"да\", \"нет\", \"да\", \"да\", \"нет\"]\ncounts = Counter(votes)\nprint(counts[\"да\"])\nprint(counts.most_common(1))",
