    private fun showLesson(index: Int) {
        currentLesson = index
        val lesson = lessons[index]
        lessonTitle.text = "Урок ${index + 1}. ${lesson.title}"
        lessonText.text = lesson.explanation
        walkthroughText.text = if (lesson.walkthrough.isNotBlank()) lesson.walkthrough else
            "Как разобраться в примере:\n1. Запусти код без изменений и посмотри на результат.\n2. Найди в коде команду или конструкцию из объяснения выше.\n3. Измени одно значение, запусти код ещё раз и сравни результат."
        example.text = lesson.example
        editor.setText(lesson.starter)
        showOutput("Запусти пример или напиши собственный код.", false)
        lessonButtonsByIndex.forEachIndexed { lessonIndex, button ->
            button.background = rounded(if (lessonIndex == index) panelAlt else panel, 14)
            button.text = "${if (completed.contains(lessonIndex)) "✓" else (lessonIndex + 1).toString()}.  ${lessons[lessonIndex].title}\n      ${lessons[lessonIndex].subtitle}"
        }
        val level = 1 + xp / 100
        val xpIntoLevel = xp % 100
        stats.text = "$xp XP   •   Уровень $level   •   Уроков пройдено: ${completed.size}/${lessons.size}"
        courseProgress.progress = completed.size
        progressText.text = "Курс пройден на ${completed.size * 100 / lessons.size}%"
        levelProgress.progress = xpIntoLevel
        levelProgressText.text = "$xpIntoLevel / 100 XP до уровня ${level + 1}"
    }

    private fun runCode(check: Boolean) {
        try {
            val runner = Python.getInstance().getModule("runner")
            val result = runner.callAttr("run_code", editor.text.toString())
                ?: throw IllegalStateException("Python runner вернул пустой результат")
            val ok = result.get("ok")?.toBoolean() ?: false
            val resultText = result.get("output")?.toString() ?: ""
            if (!ok) {
                showOutput(explainPythonError(resultText), false)
                return
            }
            if (check) {
                if (lessons[currentLesson].expected(resultText)) {
                    val firstCompletion = completed.add(currentLesson)
                    if (firstCompletion) {
                        xp += 20
                        getSharedPreferences("python_quest", MODE_PRIVATE).edit()
                            .putInt("xp", xp)
                            .putBoolean("done_$currentLesson", true)
                            .apply()
                    }
                    showLesson(currentLesson)
                    showOutput("Верно! ${if (firstCompletion) "+20 XP получено." else "Урок уже пройден."}\n\n$resultText", true)
                } else {
                    showOutput("Пока не совпало с ожидаемым результатом. Проверь код и попробуй ещё раз.\n\nВывод:\n$resultText", false)
                }
            } else {
                showOutput(resultText, true)
            }
        } catch (e: Exception) {
            showOutput("Не удалось запустить Python: ${e.message ?: e.javaClass.simpleName}", false)
        }
    }

    private fun explainPythonError(raw: String): String {
        val lines = raw.lines()
        val errorLine = lines.lastOrNull { it.contains("Error:") || it.contains("Exception:") }.orEmpty()
        val type = errorLine.substringBefore(":").substringAfterLast(" ")
        val detail = errorLine.substringAfter(":", "").trim()
        val sourceLine = lines.lastOrNull { it.contains("File \"<python-quest>\", line ") }
        val lineNumber = sourceLine?.substringAfter("line ")?.substringBefore(",")?.trim()
        val where = lineNumber?.let { "\nСтрока кода: $it." }.orEmpty()
        val explanation = when (type) {
            "SyntaxError" -> "В коде ошибка записи: проверь скобки, кавычки, двоеточия и написание команды."
            "IndentationError", "TabError" -> "Проблема с отступами. Внутри if, for, while, def и class обычно нужны 4 пробела; не смешивай пробелы и табуляцию."
            "NameError" -> "Python не знает такое имя. Проверь написание переменной или функции и убедись, что она создана до использования."
            "TypeError" -> "Операция получила значение неподходящего типа. Проверь, например, не складываешь ли ты текст и число без преобразования."
            "ValueError" -> "Тип значения подходит, но само значение некорректно для этой операции. Проверь формат данных, например текст перед int()."
            "ZeroDivisionError" -> "На ноль делить нельзя. Проверь делитель перед операцией /, // или %."
            "IndexError" -> "Обращение к элементу за пределами списка или строки. Индексы начинаются с 0; проверь длину последовательности."
            "KeyError" -> "В словаре нет такого ключа. Проверь точное написание ключа или используй dict.get(), если ключ может отсутствовать."
            "ModuleNotFoundError", "ImportError" -> "Python не смог найти нужный модуль или объект. Проверь название модуля и доступность импорта в приложении."
            "FileNotFoundError" -> "Файл не найден по указанному пути. Проверь имя и расположение файла."
            "AttributeError" -> "У объекта нет такого метода или свойства. Проверь имя после точки и тип значения."
            "RecursionError" -> "Функция вызывает себя слишком много раз. Добавь базовый случай, который останавливает рекурсию."
            "EOFError" -> "Программа ожидала ввод, которого нет в этом режиме запуска. Используй заранее заданные данные или проверь логику ввода."
            else -> "Python сообщил об ошибке. Прочитай подробность ниже и проверь строку, где она возникла."
        }
        return buildString {
            append("Разберём ошибку простыми словами.\n")
            append(explanation)
            append(where)
            if (detail.isNotBlank()) append("\nПодробность: $detail")
            append("\n\nТехнический вывод:\n")
            append(raw.trim())
        }
    }

    private fun showOutput(message: String, success: Boolean) {
        output.text = message
        output.setTextColor(if (success) green else muted)
    }

    private fun card() = LinearLayout(this).apply {
        orientation = LinearLayout.VERTICAL
        background = rounded(panel, 18)
    }

    private fun addText(parent: LinearLayout, value: String, size: Float, color: Int, bold: Boolean): TextView {
        val view = text(value, size, color, bold)
        parent.addView(view, params(top = 4, bottom = 8))
        return view
    }

    private fun text(value: String, size: Float, color: Int, bold: Boolean) = TextView(this).apply {
        text = value
        textSize = size
        setTextColor(color)
        if (bold) setTypeface(typeface, Typeface.BOLD)
        setLineSpacing(dp(2).toFloat(), 1f)
    }

    private fun rounded(color: Int, radius: Int) = GradientDrawable().apply {
        setColor(color)
        cornerRadius = dp(radius).toFloat()
        if (color == panel || color == panelAlt) setStroke(dp(1), Color.rgb(43, 59, 48))
    }

    private fun params(top: Int = 0, bottom: Int = 0) =
        LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
            topMargin = dp(top)
            bottomMargin = dp(bottom)
        }

    private fun dp(value: Int): Int = (value * resources.displayMetrics.density).toInt()
}
